import java.io.*;
import java.util.*;

public class Main {

    static int n;
    static int k;
    static String s;
    static boolean[] used;

    static boolean dfs(int u) {
        if (u < 0 || u >= n || used[u] || s.charAt(u) == '#') return false;
        if (s.charAt(u) == 'T') return true;
        used[u] = true;

        return dfs(u - k) || dfs(u + k);
    }

    static String toYesNo(boolean b) {
        return b ? "YES" : "NO";
    }

    static void solve(DataReader reader, PrintWriter out) throws IOException {
        n = reader.nextInt();
        k = reader.nextInt();

        s = reader.nextToken();

        used = new boolean[n];

        out.println(toYesNo(dfs(s.indexOf('G'))));
    }

    static class DataReader {
        private BufferedReader reader;
        private StringTokenizer st;

        DataReader(BufferedReader reader) {
            this.reader = reader;
        }

        static DataReader createFromFile(String name) throws IOException {
            return new DataReader(new BufferedReader(new FileReader(name)));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String s = reader.readLine();
                if (s == null) return null;
                st = new StringTokenizer(s);
            }

            return st.nextToken();
        }

        String nextToken() throws IOException {
            return next();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(nextToken());
        }

        long nextLong() throws IOException {
            return Long.parseLong(nextToken());
        }

        int[] readIntArray(int n) throws IOException {
            int[] result = new int[n];
            for (int i = 0; i < n; i++) {
                result[i] = nextInt();
            }
            return result;
        }

        String nextLine() throws IOException {
            return reader.readLine();
        }
    }

    public static void main(String[] args) throws IOException {
        Reader r;
        PrintWriter out;
        if (System.getProperty("ONLINE_JUDGE") == null) {
            r = new FileReader("input.txt");
            out = new PrintWriter("output.txt");
        } else {
            r = new InputStreamReader(System.in);
            out = new PrintWriter(System.out);
        }

        solve(new DataReader(new BufferedReader(r)), out);
        out.flush();
    }
}
